/**
 * Robust mathematical AR²M scoring computation for rooms
 */
export function computeFallbackRoomRecommendations(
  roomPreferences: any = {},
  mandatory: any = {}
): AR2MMatchResult[] {
  const city = (roomPreferences.preferredCity || 'Bengaluru').toLowerCase();
  const maxBudget = Number(mandatory.maxBudget || roomPreferences.budgetMax) || 25000;
  const preferredType = roomPreferences.preferredRoomTypes?.[0];

  return DEFAULT_ROOMS.map(room => {
    let score = 70;
    const reasons: MatchReason[] = [];

    // 1. City Proximity
    if (room.city.toLowerCase() === city) {
      score += 15;
      reasons.push({ type: 'positive', text: `Located in preferred city: ${room.city} (${room.locality})` });
    } else {
      score -= 15;
    }

    // 2. Budget Alignment
    if (room.rent <= maxBudget) {
      const budgetSavingsPct = Math.round(((maxBudget - room.rent) / maxBudget) * 100);
      score += 12;
      reasons.push({
        type: 'positive',
        text: `Rent ₹${room.rent.toLocaleString()}/mo is within budget limit of ₹${maxBudget.toLocaleString()} (${budgetSavingsPct}% margin)`
      });
    } else {
      score -= 20;
      reasons.push({
        type: 'warning',
        text: `Rent ₹${room.rent.toLocaleString()}/mo exceeds target budget limit by ₹${(room.rent - maxBudget).toLocaleString()}`
      });
    }

    // 3. Room Type Match
    if (preferredType && room.roomType === preferredType) {
      score += 10;
      reasons.push({ type: 'positive', text: `Exact room type match: ${room.roomType}` });
    }

    // 4. Distance / Transit factor
    if (room.distanceKm <= 3.0) {
      score += 5;
      reasons.push({ type: 'positive', text: `Close proximity: ${room.distanceKm} km from primary transit hub` });
    }

    const ar2mScore = Math.min(99, Math.max(50, score));
    const predictedScore = Math.min(99, Math.max(52, Math.round(ar2mScore * 0.98 + (room.roomId.charCodeAt(5) % 4))));
    const finalScore = Math.round((ar2mScore + predictedScore) / 2);

    return {
      matchId: `ar2m-room-${room.roomId}`,
      userId: 'active-user',
      targetType: 'room' as const,
      targetId: room.roomId,
      room,
      roomScore: ar2mScore,
      conflictPenalty: room.rent > maxBudget ? 15 : 0,
      ar2mScore,
      predictedScore,
      finalScore,
      matchingReasons: reasons,
      algorithmVersion: 'AR2M-v1.4',
      createdAt: new Date().toISOString()
    };
  }).sort((a, b) => b.finalScore - a.finalScore);
}

/**
 * Robust mathematical AR²M scoring computation for roommates
 */
export function computeFallbackRoommateRecommendations(
  roommatePreferences: any = {},
  mandatory: any = {}
): AR2MMatchResult[] {
  const city = (roommatePreferences.preferredCity || 'Bengaluru').toLowerCase();
  const targetClean = roommatePreferences.cleanliness || 'spotless';
  const targetFood = roommatePreferences.foodPreference || 'vegetarian';
  const strictNonSmoker = mandatory.strictNonSmoker ?? true;

  return DEFAULT_ROOMMATES.map(mate => {
    let score = 72;
    const reasons: MatchReason[] = [];

    // 1. City Alignment
    if (mate.preferredCity.toLowerCase() === city) {
      score += 12;
      reasons.push({ type: 'positive', text: `Cohabitant in target city: ${mate.preferredCity} (${mate.preferredLocality || 'Centrally located'})` });
    }

    // 2. Cleanliness Alignment
    if (mate.cleanliness === targetClean) {
      score += 10;
      reasons.push({ type: 'positive', text: `High hygiene alignment: Both prefer ${targetClean} living standards` });
    }

    // 3. Dietary Compatibility
    if (mate.foodPreference === targetFood || targetFood === 'any' || mate.foodPreference === 'any') {
      score += 8;
      reasons.push({ type: 'positive', text: `Dietary harmony: Compatible food preferences (${mate.foodPreference})` });
    }

    // 4. Strict Non-Smoker Hard Constraint Check
    if (strictNonSmoker && mate.smokingPreference === 'smoker') {
      score -= 30;
      reasons.push({ type: 'warning', text: 'Hard Conflict: Active smoker policy mismatch' });
    } else if (mate.smokingPreference === 'strictly-non-smoker') {
      score += 6;
      reasons.push({ type: 'positive', text: 'Non-smoker alignment: Shared clean air living space' });
    }

    const ar2mScore = Math.min(99, Math.max(52, score));
    const predictedScore = Math.min(99, Math.max(54, Math.round(ar2mScore * 0.97 + (mate.uid.charCodeAt(10) % 5))));
    const finalScore = Math.round((ar2mScore + predictedScore) / 2);

    return {
      matchId: `ar2m-mate-${mate.uid}`,
      userId: 'active-user',
      targetType: 'roommate' as const,
      targetId: mate.uid,
      roommate: mate,
      roommateScore: ar2mScore,
      conflictPenalty: 0,
      ar2mScore,
      predictedScore,
      finalScore,
      matchingReasons: reasons,
      algorithmVersion: 'AR2M-v1.4',
      createdAt: new Date().toISOString()
    };
  }).sort((a, b) => b.finalScore - a.finalScore);
}

/**
 * Robust mathematical AR²M scoring computation for combined search
 */
export function computeFallbackCombinedRecommendations(
  roomPreferences: any = {},
  roommatePreferences: any = {},
  mandatory: any = {}
): AR2MMatchResult[] {
  const roomResults = computeFallbackRoomRecommendations(roomPreferences, mandatory);
  const mateResults = computeFallbackRoommateRecommendations(roommatePreferences, mandatory);

  const combined: AR2MMatchResult[] = [];
  const limit = Math.min(roomResults.length, mateResults.length, 30);

  for (let i = 0; i < limit; i++) {
    const rMatch = roomResults[i];
    const mMatch = mateResults[i % mateResults.length];
    const avgScore = Math.round((rMatch.finalScore + mMatch.finalScore) / 2);

    combined.push({
      matchId: `ar2m-comb-${i + 1}`,
      userId: 'active-user',
      targetType: 'combined' as const,
      targetId: `pair-${rMatch.targetId}-${mMatch.targetId}`,
      room: rMatch.room,
      roommate: mMatch.roommate,
      roomScore: rMatch.roomScore,
      roommateScore: mMatch.roommateScore,
      conflictPenalty: 0,
      ar2mScore: Math.round(((rMatch.ar2mScore || 85) + (mMatch.ar2mScore || 85)) / 2),
      predictedScore: Math.round(((rMatch.predictedScore || 85) + (mMatch.predictedScore || 85)) / 2),
      finalScore: avgScore,
      matchingReasons: [
        { type: 'positive', text: `High AR²M Score: Compatible flatmate (${mMatch.roommate?.displayName}) paired with ${rMatch.room?.roomType} in ${rMatch.room?.locality}` },
        ...(rMatch.matchingReasons.slice(0, 2)),
        ...(mMatch.matchingReasons.slice(0, 2))
      ],
      algorithmVersion: 'AR2M-v1.4',
      createdAt: new Date().toISOString()
    });
  }

  return combined.sort((a, b) => b.finalScore - a.finalScore);
}
